<div class="narrow booking-container"><a class="back-link" href="<?= e(url($step===1?'rooms':'booking',$step===1?['action'=>'show','id'=>$room['id']]:['action'=>'create','room'=>$room['id'],'date'=>$values['date'],'start_time'=>$values['start_time'],'end_time'=>$values['end_time']])) ?>"><?= icon('chevron-left') ?><?= $step===1?'Voltar para a sala':'Etapa anterior' ?></a><div class="booking-steps"><span class="step active"><b><?= $step===2?'✓':'1' ?></b>Data e horário</span><?= icon('chevron-right') ?><span class="step <?= $step===2?'active':'' ?>"><b>2</b>Finalizar</span></div><article class="card room-summary"><img src="public/assets/images/<?= e($room['image']) ?>" width="64" height="64" alt="<?= e($room['name']) ?>"><div><small class="inline-meta"><?= icon(room_icon($room['type'])) ?><?= e($room['type']) ?></small><h3><?= e($room['name']) ?></h3><small class="inline-meta"><?= icon('users') ?><?= $room['capacity'] ?> pessoas <?= icon('map-pin') ?><?= e($room['floor']) ?></small></div></article>
<section class="card card-body section-gap"><h3><?= $step===1?'Data e horário':'Finalizar reserva' ?></h3><?php form_errors($errors); ?><form method="post" action="<?= e(url('booking',['action'=>$step===1?'check':'store','room'=>$room['id']])) ?>" class="stacked-form"><?= csrf_field() ?>
<?php if($step===1): ?><div class="field"><label for="date">Data da reserva</label><input type="date" id="date" name="date" value="<?= e($values['date']) ?>" min="<?= date('Y-m-d') ?>" required><?php if(isset($errors['date'])): ?><p class="field-error"><?= e($errors['date']) ?></p><?php endif; ?></div><div class="form-grid"><?php foreach(['start_time'=>'Início','end_time'=>'Término'] as $key=>$label): $opts=[];foreach(range($key==='start_time'?7:8,$key==='start_time'?17:18) as $h){$t=sprintf('%02d:00',$h);$opts[$t]=$t;}select_field($key,$label,$opts,$values,$errors);endforeach; ?></div><button class="button full">Continuar <?= icon('chevron-right') ?></button>
<?php else: foreach(['date','start_time','end_time'] as $key): ?><input type="hidden" name="<?= $key ?>" value="<?= e($values[$key]) ?>"><?php endforeach; ?><div class="booking-date"><?= e(date_br($values['date']).' · '.$values['start_time'].' – '.$values['end_time']) ?></div><?php field('purpose','Finalidade',$values,$errors,'text',true,180);field('notes','Observações (opcional)',$values,$errors,'textarea',false,3000); ?><button class="button full"><?= icon('check') ?>Confirmar solicitação</button><?php endif; ?></form></section></div>

